/// The path to the default (unnamed) collapsed directory icon.
pub(crate) const DIRECTORY_ICON_COLLAPSED: &str = "icons/file_icons/material/folder.svg";
/// The path to the default (unnamed) expanded directory icon.
pub(crate) const DIRECTORY_ICON_EXPANDED: &str = "icons/file_icons/material/folder-open.svg";

/// Returns a mapping of file associations to icon keys.
fn icon_keys_by_association(
    associations_by_icon_key: &[(&str, &[&str])],
) -> HashMap<String, String> {
    let mut icon_keys_by_association = HashMap::default();
    for (icon_key, associations) in associations_by_icon_key {
        for association in *associations {
            icon_keys_by_association.insert(association.to_string(), icon_key.to_string());
        }
    }

    icon_keys_by_association
}

/// Returns the Material icon theme's file-stem -> icon-key table.
pub(crate) fn material_file_stems() -> HashMap<String, String> {
    icon_keys_by_association(FILE_STEMS_BY_ICON_KEY)
}

/// Returns the Material icon theme's file-suffix -> icon-key table.
pub(crate) fn material_file_suffixes() -> HashMap<String, String> {
    icon_keys_by_association(FILE_SUFFIXES_BY_ICON_KEY)
}

/// Returns the Material icon theme's icon-key -> asset-path table.
pub(crate) fn material_file_icons() -> HashMap<String, String> {
    HashMap::from_iter(
        FILE_ICONS
            .iter()
            .map(|(key, path)| (key.to_string(), path.to_string())),
    )
}

/// Returns the Material icon theme's named-directory -> (collapsed, expanded) table.
pub(crate) fn material_named_directory_icons() -> HashMap<String, (String, String)> {
    HashMap::from_iter(NAMED_DIRECTORY_ICONS.iter().map(|(name, collapsed, expanded)| {
        (name.to_string(), (collapsed.to_string(), expanded.to_string()))
    }))
}
